import {Game,WEAPONS,SECTORS,WORLD,clamp} from './game.js';
import {Renderer} from './render.js';
import {AudioEngine} from './audio.js';
const $=id=>document.getElementById(id),canvas=$('game'),audio=new AudioEngine();
let renderer,game,last=0,hudClock=0,noticeTimeout,bannerTimeout,difficulty='normal',mouseAim=false,pointer={x:0,y:0},guidePaused=false;
const held=new Set(),pressed=new Set();
const gameKeys=new Set(['KeyA','KeyD','KeyW','KeyS','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','KeyJ','KeyK','KeyL','KeyH','KeyQ','ShiftLeft','ShiftRight']);
const formatTime=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
function notice(text){$('notification').textContent=text;$('notification').classList.add('show');clearTimeout(noticeTimeout);noticeTimeout=setTimeout(()=>$('notification').classList.remove('show'),3500);}
function clearInput(){held.clear();pressed.clear();mouseAim=false;}
function showState(){for(const [id,state]of [['menu','menu'],['pause-screen','paused'],['death-screen','dead'],['victory','victory']])$(id).classList.toggle('hidden',game.state!==state);const running=game.state==='playing';$('hud').classList.toggle('hidden',game.state==='menu');$('pause').classList.toggle('hidden',!running);$('touch-controls').classList.toggle('hidden',!running);if(!running){clearInput();$('sector-banner').classList.add('hidden');}if(game.state==='paused')$('resume').focus();if(game.state==='dead')$('retry').focus();if(game.state==='victory')$('replay').focus();if(game.state==='menu')$('start').focus();}
function event(e){audio.play(e);switch(e.type){case'notice':notice(e.text);break;case'sector':{const s=SECTORS[e.sector],el=$('sector-banner');el.querySelector('small').textContent=`AREA 0${e.sector+1}`;el.querySelector('strong').textContent=s.name;el.querySelector('span').textContent=s.objective;el.classList.remove('hidden');clearTimeout(bannerTimeout);bannerTimeout=setTimeout(()=>el.classList.add('hidden'),3100);break;}
case'pause':case'resume':case'death':showState();break;case'victory':finish();break;}}
function start(){clearInput();game.difficulty=difficulty;game.start();showState();canvas.focus();audio.init();if(window.innerHeight>window.innerWidth)notice('横过手机，视野更开阔 · 按住「火」持续射击');else setTimeout(()=>{if(game.state==='playing'&&game.maxX<900)notice('按住 J 或鼠标左键射击 · 空格二段跳 · Shift 冲刺');},4000);updateHUD();}
function menu(){game.state='menu';clearInput();showState();$('boss-hud').classList.add('hidden');}
function retry(){game.retry();clearInput();showState();canvas.focus();updateHUD();}
function pause(){game.pause();clearInput();if(game.state==='playing')canvas.focus();}
function finish(){const rank=game.deaths===0&&game.time<220?'S':game.deaths<=2?'A':game.deaths<=5?'B':'C';$('rank').textContent=rank;$('final-score').textContent=game.score.toLocaleString();$('final-time').textContent=formatTime(game.time);$('final-kills').textContent=game.kills+' / '+game.deaths;let best=game.score;try{const key='red-falcon-best-'+difficulty;best=Math.max(game.score,Number(localStorage.getItem(key))||0);localStorage.setItem(key,String(best));}catch{}$('best-result').textContent=`${difficulty==='normal'?'标准':'老兵'}模式最佳纪录：${best.toLocaleString()}${game.score>=best?' · 新纪录':''}`;showState();}
function updateHUD(){if(game.state==='menu')return;const p=game.player,s=SECTORS[game.sector],w=WEAPONS[p.weapon];$('health-number').textContent=Math.ceil(p.hp);$('health-bar').firstElementChild.style.width=p.hp+'%';$('health-bar').firstElementChild.style.background=p.hp<30?'#ff7049':'#e4f69e';$('dash-status').textContent=p.dashCd>0?`冲刺 ${p.dashCd.toFixed(1)}s`:'冲刺就绪';$('grenade-count').textContent='◆ '.repeat(p.grenades)||'手雷耗尽';$('sector-label').textContent=`0${game.sector+1} / ${s.name}`;$('objective-label').textContent=game.boss.active?'摧毁钢铁守卫':s.objective;$('progress').style.width=clamp(game.maxX/(WORLD-300)*100,0,100)+'%';$('score').textContent=String(game.score).padStart(6,'0');$('timer').textContent=formatTime(game.time);$('weapon-code').textContent=`0${p.weapon+1} / ${w.code}`;$('weapon-name').firstChild.textContent=w.name+' ';$('weapon-hint').textContent=p.unlocked.length>1?'Q 切换武器 · 已解锁 '+p.unlocked.length+'/3':'拾取 S / R 解锁新武器';$('boss-hud').classList.toggle('hidden',!game.boss.active||game.boss.dead);$('boss-hud').querySelector('.boss-track i').style.width=game.boss.hp/game.boss.maxHp*100+'%';$('boss-phase').textContent=game.boss.phase===2?'阶段 II · 过载':'阶段 I';}
function keyDown(e){if(e.code==='Escape'){
  if($('guide').open){$('guide').close();return;}
  if(game.state==='playing'||game.state==='paused'){e.preventDefault();pause();}return;}
  if($('guide').open)return;
  if(e.code==='KeyM'&&!e.repeat){toggleSound();return;}if(e.code==='KeyF'&&!e.repeat){fullScreen();return;}
  if(e.code==='Enter'&&!e.repeat&&(e.target===document.body||e.target===canvas)){if(game.state==='menu')start();else if(game.state==='dead')retry();else if(game.state==='paused')pause();}
  if(game.state!=='playing')return;if(gameKeys.has(e.code)){e.preventDefault();if(!held.has(e.code))pressed.add(e.code);held.add(e.code);if(e.code==='KeyJ'||e.code==='KeyW'||e.code==='KeyS')mouseAim=false;}
}
window.addEventListener('keydown',keyDown);window.addEventListener('keyup',e=>held.delete(e.code));
window.addEventListener('blur',()=>{clearInput();if(game.state==='playing')game.pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(game.state==='playing')game.pause();}});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){pointer={x:e.clientX,y:e.clientY};if(held.has('Mouse0'))mouseAim=true;}});
canvas.addEventListener('pointerdown',e=>{if(game.state!=='playing'||e.pointerType==='touch')return;e.preventDefault();canvas.focus();audio.init();pointer={x:e.clientX,y:e.clientY};mouseAim=true;const key='Mouse'+e.button;if(!held.has(key))pressed.add(key);held.add(key);canvas.setPointerCapture(e.pointerId);});
window.addEventListener('pointerup',e=>held.delete('Mouse'+e.button));canvas.addEventListener('pointercancel',clearInput);canvas.addEventListener('contextmenu',e=>e.preventDefault());
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();if(game.state!=='playing')return;b.setPointerCapture(e.pointerId);const k=b.dataset.key;if(!held.has(k))pressed.add(k);held.add(k);mouseAim=false;audio.init();});const release=()=>held.delete(b.dataset.key);b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);}
async function toggleSound(){await audio.init();const on=audio.toggle();$('sound').textContent=on?'♫':'♪';$('sound').setAttribute('aria-label',on?'关闭声音':'开启声音');$('sound').setAttribute('aria-pressed',String(on));notice(on?'声音已开启':'声音已关闭');}
async function fullScreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await $('app').requestFullscreen();}catch{notice('当前浏览器不支持全屏，可使用浏览器的全屏模式');}}
$('start').onclick=start;$('replay').onclick=start;$('resume').onclick=pause;$('pause').onclick=pause;$('restart').onclick=retry;$('retry').onclick=retry;for(const id of ['exit','death-exit','victory-exit'])$(id).onclick=menu;$('sound').onclick=toggleSound;$('fullscreen').onclick=fullScreen;
$('help').onclick=()=>{guidePaused=game.state==='playing';if(guidePaused)game.pause();$('guide').showModal();};const closeGuide=()=>$('guide').close();$('close-guide').onclick=closeGuide;$('guide-ready').onclick=closeGuide;$('guide').addEventListener('close',()=>{if(guidePaused&&game.state==='paused'){guidePaused=false;pause();}});
document.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.difficulty;document.querySelectorAll('[data-difficulty]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected));});$('difficulty-note').textContent=difficulty==='normal'?'护甲保护 · 检查点续战':'更高伤害 · 更快敌弹';});
window.addEventListener('resize',()=>renderer?.resize());document.addEventListener('fullscreenchange',()=>{$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'退出全屏':'进入全屏');renderer?.resize();});
try{game=new Game({onEvent:event});renderer=new Renderer(canvas);Object.defineProperty(window,'redFalcon',{value:Object.freeze({snapshot:()=>game.snapshot(),get metrics(){return{width:renderer.width,height:renderer.height,scale:renderer.scale,particles:game.particles.length};}})});
  function frame(time){try{const dt=Math.min((time-last)/1000||.016,.034);last=time;const input={held,pressed,aim:mouseAim?renderer.point(pointer.x,pointer.y,game.camera):null};const stalled=game.hitstop>0;game.update(dt,input);if(!stalled)pressed.clear();audio.update(dt,game.state,game.boss.active);renderer.render(game);hudClock+=dt;if(hudClock>.08){hudClock=0;updateHUD();}requestAnimationFrame(frame);}catch(error){$('boot-error').classList.remove('hidden');console.error('Game runtime error',error);}}
  requestAnimationFrame(frame);
}catch(error){$('boot-error').classList.remove('hidden');console.error('Game failed to initialize',error);}
